function persist(){store.set('users',state.users);store.set('frontendAccounts',state.frontendAccounts);store.set('serviceAdmins',state.serviceAdmins);store.set('roles',state.roles);store.set('services',state.services);store.set('activity',state.activity);store.set('alerts',state.alerts);store.set('moduleData',state.moduleData);store.set('tickets',state.tickets);store.set('contentItems',state.contentItems);store.set('settings',state.settings)}
