function renderAudit(){const q=($('#auditSearch')?.value||'').toLowerCase(),f=$('#auditFilter')?.value||'All events';const rows=state.activity.filter(a=>(!q||[a.text,a.time].join(' ').toLowerCase().includes(q))&&(f==='All events'||(f==='Access'&&/user|admin|sign-in|account/i.test(a.text))||(f==='Configuration'&&/setting|configuration|policy/i.test(a.text))||(f==='Content'&&/content|publisher|post/i.test(a.text))||(f==='Security'&&/security|mfa|sign-in|access/i.test(a.text))));$('#auditRows').innerHTML=rows.map((a,i)=>`<tr><td><div class="user-cell"><div class="service-logo">${icon(a.icon||'activity')}</div><div><strong>${a.text.replace(/<[^>]*>/g,'')}</strong><small>Event ID: AUD-${String(i+1).padStart(5,'0')}</small></div></div></td><td>Super Admin</td><td>Control Center</td><td>${esc(a.time)}</td><td>${pill(/security|mfa|sign-in/i.test(a.text)?'Security':'Configuration')}</td><td><button class="mini-icon-btn" data-action="audit-detail" data-index="${i}" title="View details">${icon('eye')}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state">No audit records match this filter.</div></td></tr>';$('#auditCount').textContent=`${rows.length} audit entries`;}
