$('#globalSearch').addEventListener('keydown',e=>{if(e.key!=='Enter')return;const q=e.target.value.trim().toLowerCase();if(!q)return;const service=state.services.find(s=>s.name.toLowerCase().includes(q));const page=Object.entries(pageNames).find(([k,v])=>v.toLowerCase().includes(q));const frontend=state.frontendAccounts.find(u=>u.name.toLowerCase().includes(q)||u.email.toLowerCase().includes(q)||(u.mobile||'').toLowerCase().includes(q));const admin=state.serviceAdmins.find(u=>u.name.toLowerCase().includes(q)||u.email.toLowerCase().includes(q)||(u.mobile||'').toLowerCase().includes(q));if(service){navigate('services');state.serviceSearch=service.name;const inp=$('#serviceSearch');if(inp){inp.value=service.name;inp.dispatchEvent(new Event('input'))}}else if(frontend){navigate('users');$('#frontendSearch').value=frontend.name;renderFrontendRows()}else if(admin){navigate('serviceAdmins');$('#adminSearch').value=admin.name;renderAdminRows()}else if(page)navigate(page[0]);else{navigate('services');state.serviceSearch=q;const inp=$('#serviceSearch');if(inp){inp.value=q;inp.dispatchEvent(new Event('input'))}}e.target.value=''});
